# More careful column analysis
grid = np.array(test_input)
rows, cols = grid.shape

print("=== Checking exact column positions ===")

left_col_counts = {}
right_col_counts = {}

for row_idx in range(rows):
    row = grid[row_idx]

    for c in range(7):
        if row[c] == 9:
            left_col_counts[c] = left_col_counts.get(c, 0) + 1

    for c_rel in range(7):  # Right side relative col
        if row[8 + c_rel] == 4:
            right_col_counts[c_rel] = right_col_counts.get(c_rel, 0) + 1

print(f"Left side 9 count per col (0-6): {dict(sorted(left_col_counts.items()))}")
print(f"Right side 4 count per rel col (0-6): {dict(sorted(right_col_counts.items()))}")

# Now check mirroring: right col c mirrors to left col (6-c)
mirrored_left_cols = {c: count for c, count in right_col_counts.items()}
mirrored = {}
for orig_col, count in left_col_counts.items():
    mirrored_mirror = 6 - orig_col
    mirrored[mirrored_mirror] = mirrored.get(mirrored_mirror, 0) + count

print(f"\nMirrored 9 positions: {dict(sorted(mirrored.items()))}")
print(f"Direct right 4 positions: {dict(sorted(right_col_counts.items()))}")

